transforms.code:

security = value['security']
canCreate = False
canEdit = False
if security['userCRUD'] is not None and security['userId'] is not None:
	if security['userCRUD']['isGatewayAdmin'] or security['userCRUD']['scheduleShifts']['enabled']:
		canCreate = True
		canEdit = True if value['eventInfo']['shiftBlockId'] is not None else False

action = {"canCreate": canCreate, "canDelete": canEdit, "canRead": True, "canUpdate": canEdit}

return action

onChange.script:
if currentValue.value != 'Production':
	self.custom.values.wo = None
	self.custom.values.qty = None


if origin == 'Browser':
	shiftNameId = currentValue.value
	shiftId = None		
	if isinstance(shiftNameId, int): shiftId = system.kanoa.utilities.getFieldValue('shiftId', system.kanoa.shift.getShifts({'assetPath': self.view.custom.values.assetPath, 'shiftNameId': shiftNameId}))

return

config.script:
params = {'color': self.view.custom.values.shiftColor}	
system.perspective.openPopup('color picker', 'kanoa/core/templates/colorPicker/main', params=params, overlayDismiss=True)
return

if self.view.custom.userAction.canUpdate:
	self.view.getChild("root").openEditor()
else:
	system.perspective.sendMessage('showFailerToast', 'No permissions to update downtime events.')

return

